/**
 * 掃描所有 session 檔案，建立索引
 */
private async scanAllSessions(): Promise<void> {
  const glob = new Glob('**/*.jsonl');
  const sessions: CachedSession[] = [];

  for await (const file of glob.scan({ cwd: this.baseDir, absolute: true })) {
    const filename = basename(file);
    if (!filename.startsWith('rollout-')) continue;

    const meta = await readMainSessionMeta(file);
    if (meta) {
      try {
        const stats = await stat(file);
        sessions.push({
          path: file,
          mtime: stats.mtime.getTime(),
          cwd: meta.cwd,
        });
      } catch {
        // 忽略無法 stat 的檔案
      }
    }
  }

  // 建立 cwd 索引
  this.cache.clear();
  for (const session of sessions) {
    if (!this.cache.has(session.cwd)) {
      this.cache.set(session.cwd, []);
    }
    this.cache.get(session.cwd)!.push(session);
  }

  // 每個 cwd 內按 mtime 排序（降序）
  for (const [, cwdSessions] of this.cache) {
    cwdSessions.sort((a, b) => b.mtime - a.mtime);
  }
}

input.new_string:
/**
 * 掃描所有 session 檔案，建立索引（parallel meta + stat）
 */
private async scanAllSessions(): Promise<void> {
  const paths = await this.collectRolloutPaths();
  const sessions = await this.resolveMainSessions(paths);
  this.replaceCache(sessions);
}

/** Glob all rollout-*.jsonl paths under baseDir */
private async collectRolloutPaths(): Promise<string[]> {
  const glob = new Glob('**/*.jsonl');
  const paths: string[] = [];
  for await (const file of glob.scan({ cwd: this.baseDir, absolute: true })) {
    if (basename(file).startsWith('rollout-')) {
      paths.push(file);
    }
  }
  return paths;
}

/**
 * Parallel readMainSessionMeta + stat for a list of rollout paths.
 * Subagent / malformed files are dropped (null).
 */
private async resolveMainSessions(
  paths: string[]
): Promise<CachedSession[]> {
  const results = await Promise.all(
    paths.map(async (file): Promise<CachedSession | null> => {
      const meta = await readMainSessionMeta(file);
      if (!meta) return null;
      try {
        const stats = await stat(file);
        return {
          path: file,
          mtime: stats.mtime.getTime(),
          cwd: meta.cwd,
        };
      } catch {
        return null;
      }
    })
  );
  return results.filter((s): s is CachedSession => s !== null);
}

/** Replace in-memory cwd index from a flat session list */
private replaceCache(sessions: CachedSession[]): void {
  this.cache.clear();
  for (const session of sessions) {
    if (!this.cache.has(session.cwd)) {
      this.cache.set(session.cwd, []);
    }
    this.cache.get(session.cwd)!.push(session);
  }
  for (const [, cwdSessions] of this.cache) {
    cwdSessions.sort((a, b) => b.mtime - a.mtime);
  }
}

private buildPathSet(): Set<string> {
  const known = new Set<string>();
  for (const sessions of this.cache.values()) {
    for (const s of sessions) known.add(s.path);
  }
  return known;
}

/**
 * Sync cache with filesystem: add missing main sessions, prune deleted.
 * Returns true when the in-memory index changed.
 */
private async syncWithFilesystem(): Promise<boolean> {
  const existingPaths = await this.collectRolloutPaths();
  const existingSet = new Set(existingPaths);
  const knownPaths = this.buildPathSet();

  let changed = false;

  // Prune deleted / moved files
  for (const [cwd, sessions] of [...this.cache.entries()]) {
    const remaining = sessions.filter((s) => existingSet.has(s.path));
    if (remaining.length === sessions.length) continue;
    changed = true;
    if (remaining.length === 0) {
      this.cache.delete(cwd);
    } else {
      this.cache.set(cwd, remaining);
    }
  }

  // Resolve only paths not already cached
  const candidates = existingPaths.filter((p) => !knownPaths.has(p));
  if (candidates.length === 0) return changed;

  const discovered = await this.resolveMainSessions(candidates);
  if (discovered.length === 0) return changed;

  changed = true;
  for (const session of discovered) {
    if (!this.cache.has(session.cwd)) {
      this.cache.set(session.cwd, []);
    }
    this.cache.get(session.cwd)!.push(session);
    this.cache.get(session.cwd)!.sort((a, b) => b.mtime - a.mtime);
  }
  return changed;
}

/**
 * List all known main sessions (for --list / findLatest).
 * Ensures cache is initialized, then syncs with filesystem so sessions
 * created since the last disk cache write are not missed.
 */
async listAllSessions(options?: {
  project?: string;
}): Promise<CachedSession[]> {
  await this.init();
  const changed = await this.syncWithFilesystem();
  if (changed) {
    await this.saveToDisk();
  }

  const all: CachedSession[] = [];
  const pattern = options?.project?.toLowerCase();
  for (const [cwd, sessions] of this.cache) {
    if (pattern && !cwd.toLowerCase().includes(pattern)) continue;
    all.push(...sessions);
  }
  all.sort((a, b) => b.mtime - a.mtime);
  return all;
}

