/** Initial head-read size; grows until first-line newline or EOF */
const META_HEAD_INITIAL_SIZE = 8192;

/** Cap parallel meta/stat workers to avoid fd / I/O storms on large installs */
const RESOLVE_CONCURRENCY = 64;

/**
 * Run async mapper over items with a fixed concurrency pool.
 */
async function mapPool<T, R>(
  items: T[],
  concurrency: number,
  fn: (item: T) => Promise<R>
): Promise<R[]> {
  if (items.length === 0) return [];
  const results = new Array<R>(items.length);
  let next = 0;
  const workers = Array.from(
    { length: Math.min(concurrency, items.length) },
    async () => {
      while (true) {
        const i = next++;
        if (i >= items.length) return;
        results[i] = await fn(items[i]!);
      }
    }
  );
  await Promise.all(workers);
  return results;
}

/**
 * 讀取 Codex JSONL 首行的 session_meta
 * 回傳 cwd（主 session）或 null（非 session_meta、subagent、或讀取失敗）
 *
 * Progressive head-read until the first newline or EOF — never assumes a
 * fixed max line size. Typical session_meta is ≪8KB; pathological lines
 * grow the window until the newline (JSONL) or the whole file is consumed.
 */
export async function readMainSessionMeta(
  filePath: string
): Promise<{ cwd: string } | null> {
  try {
    const file = Bun.file(filePath);
    const size = file.size;
    if (size === 0) return null;

    let chunkSize = META_HEAD_INITIAL_SIZE;
    let firstLine: string | null = null;
    while (true) {
      const readSize = Math.min(size, chunkSize);
      const content = await file.slice(0, readSize).text();
      const nl = content.indexOf('\n');
      if (nl !== -1) {
        firstLine = content.slice(0, nl);
        break;
      }
      if (readSize >= size) {
        // Entire file has no newline — treat whole content as the first line
        firstLine = content;
        break;
      }
      // Grow window (×4) until we capture the newline
      chunkSize = Math.min(chunkSize * 4, size);
    }
    if (!firstLine) return null;

    const meta = JSON.parse(firstLine);
    if (meta.type !== 'session_meta') return null;

    const payload = meta.payload as SessionMetaPayload | undefined;
    if (!payload?.cwd) return null;

    // 排除 subagent（source 為物件且含 subagent 屬性）
    const source = payload.source;
    if (typeof source === 'object' && source !== null && 'subagent' in source) {
      return null;
    }

    return { cwd: payload.cwd };
  } catch {
    return null;
  }
}

