  const all: CachedSession[] = [];
  const pattern = options?.project?.toLowerCase();
  for (const [cwd, sessions] of this.cache) {
    if (pattern && !cwd.toLowerCase().includes(pattern)) continue;
    all.push(...sessions);
  }
  all.sort((a, b) => b.mtime - a.mtime);
